"""A15 native sampled geometry, standalone viewer and scientific comparison."""
import base64,gzip,hashlib,json,math
from pathlib import Path
import numpy as np
from reportlab.graphics.shapes import Drawing,String
from reportlab.graphics.charts.lineplots import LinePlot
from reportlab.graphics import renderSVG,renderPDF
from reportlab.lib import colors
import reportlab,pypdfium2 as pdfium
from PIL import Image,ImageDraw,ImageFont

ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'wtc1_simulation_v8/output/aircraft_a15'

def main():
    dst=OUT/'visualisation';assert not dst.exists();s=json.loads((OUT/'campaign_review.json').read_text());assert s['cases'];dst.mkdir()
    rows=s['cases'];allrows=rows+s.get('partial_cases',[]);palette=[colors.HexColor('#288679'),colors.HexColor('#ab6337')]
    fig=Drawing(1120,810);fig.add(String(42,771,'AIRCRAFT-A15 : avion complet contre facade deformable',fontSize=20));fig.add(String(42,741,'Essais exploratoires a 200 m/s. Temps natif 10 ms = 0,01 s. Aucune trajectoire imposee.',fontSize=12));fig.add(String(42,716,'Pas de rupture, delamination ou ecrasement qualifies. Criteres echoues conserves dans le rapport.',fontSize=12))
    arrays=[np.load(OUT/'r0'/r['case']['id']/'balance_history_SI.npz') for r in allrows]
    for i,r in enumerate(allrows):fig.add(String(45+510*i,687,'Facteur de pas '+str(r['case']['dt_scale'])+' : '+('partiel, plafond de calcul' if 'status' in r else '10 ms atteintes'),fontSize=12,fillColor=palette[i]))
    for key,title,factor,x,y in [('contact_impulse_Ns','Impulsion X sur la facade (kN.s)',.001,80,395),('generated_energy_J','Energie hors translation (MJ)',1e-6,635,395),('energy_residual_J','Residuel du bilan global (kJ)',.001,80,82)]:
        c=LinePlot();c.x=x;c.y=y;c.width=410;c.height=215;c.joinedLines=1;c.xValueAxis.valueMin=0;c.xValueAxis.valueMax=10;c.data=[]
        for i,z in enumerate(arrays):
            ix=np.unique(np.r_[np.arange(0,len(z['time_s']),max(1,len(z['time_s'])//430)),len(z['time_s'])-1]);v=z[key][:,0] if key=='contact_impulse_Ns' else z[key];c.data.append(list(zip((z['time_s'][ix]*1000).tolist(),(v[ix]*factor).tolist())));c.lines[i].strokeColor=palette[i];c.lines[i].strokeWidth=1.4
        fig.add(c);fig.add(String(x,y+240,title,fontSize=14));fig.add(String(x+130,y-31,'Temps physique (ms)',fontSize=11))
    r=rows[0];lines=[f"Avion natif : {r['native_aircraft_mass_kg']:.1f} kg.",'Facade : 3 etages representatifs deformables.',f"Deplacement facade echantillonne : {r['maximum_facade_displacement_mm']:.1f} mm.",'Materiaux et masse du prototype conserves.','Modele sans rupture et sans carburant resolu.','Contact et limites numeriques encore a qualifier.','Impulsion et appuis issus des historiques natifs.','Animation issue du solveur, deplacements x1.']
    for i,line in enumerate(lines):fig.add(String(635,311-27*i,line,fontSize=12))
    renderSVG.drawToFile(fig,str(dst/'bilans_impact.svg'));pdf=pdfium.PdfDocument(renderPDF.drawToString(fig));page=pdf[0];bm=page.render(scale=1.4);bm.to_pil().save(dst/'bilans_impact.png');bm.close();page.close();pdf.close()
    case=rows[0]['case']['id'];d=OUT/'r0'/case;z=np.load(d/'verified_states_SI.npz');m=json.loads((d/'mesh.json').read_text());g=json.loads((d/'generation.json').read_text());L=arrays[0]
    tri=[[n-1 for n in q] for q in m['original_triangle_node_ids']];wall=[[n-1 for n in q] for q in m['facade_quads_node_ids']];beams=[[n-1 for n in q] for q in m['original_beam_node_ids']]
    X=np.asarray(z['initial_positions_m'],dtype='<f8');U=np.asarray(z['displacement_m'],dtype='<f4');raw=X.tobytes()+U.tobytes();compressed=gzip.compress(raw,compresslevel=6,mtime=0);assert gzip.decompress(compressed)==raw
    # New scientific raster drawn directly from native nodes; no geometry interpolation.
    im=Image.new('RGB',(1680,1240),'#111e2b');draw=ImageDraw.Draw(im)
    font=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',25);small=ImageFont.truetype('C:/Windows/Fonts/arial.ttf',21)
    draw.text((35,25),'AIRCRAFT-A15 — avion complet contre façade déformable',fill='#edf4fa',font=font)
    draw.text((35,68),'État natif à 10,000361 ms · déplacements ×1 · prototype exploratoire',fill='#b9ccdd',font=small)
    for close,cy in [(False,370),(True,900)]:
        sc=83 if close else 19;center=np.array([0.,0.,0.]) if close else np.array([15.,0.,0.]);xyz=X+U[-1]-center;initial=X-center
        def projected(v):return np.column_stack([840+sc*(.819*v[:,0]+.574*v[:,1]),cy-sc*(.94*v[:,2]-.342*(-.574*v[:,0]+.819*v[:,1]))])
        points=projected(xyz);p0=projected(initial)
        for faces,color,pp in [(tri,'#455a6a',p0),(wall,'#e4a16d',points),(tri,'#53d1b2',points)]:
            for face in faces:
                ij=np.asarray(face);xy=pp[ij]
                if close and (np.all(abs(xyz[ij,0])>6) or np.all(abs(xyz[ij,1])>6) or np.all(abs(xyz[ij,2])>4)):continue
                if np.any((xy[:,0]<0)|(xy[:,0]>1680)|(xy[:,1]<(640 if close else 115))|(xy[:,1]>(1160 if close else 610))):continue
                draw.line([tuple(v) for v in xy]+[tuple(xy[0])],fill=color,width=1)
        draw.text((35,cy-220),'Contact du nez' if close else 'Vue de l’avion et des trois étages de façade',fill='#edf4fa',font=small)
    draw.text((35,1185),'Vert : avion · orange : façade · gris : avion initial. Rupture et écrasement absents du modèle.',fill='#b9ccdd',font=small)
    im.save(dst/'impact_natif_10ms.png')
    payload={'case':case,'nn':len(X),'nt':len(U),'time_ms':(z['time_s']*1000).tolist(),'triangles':tri,'wall':wall,'beams':beams,'impulse_Ns':np.interp(z['time_s'],L['time_s'],L['contact_impulse_Ns'][:,0]).tolist(),'energy_J':np.interp(z['time_s'],L['time_s'],L['generated_energy_J']).tolist(),'residual_J':np.interp(z['time_s'],L['time_s'],L['energy_residual_J']).tolist(),'facade_displacement_mm':[q['maximum_facade_displacement_mm'] for q in r['state_diagnostics']]}
    html='''<!doctype html><html lang="fr"><meta charset="utf-8"><title>A15 — avion et façade</title><style>body{margin:0;background:#111e2b;color:#edf4fa;font:16px system-ui}main{max-width:1240px;margin:auto;padding:24px}h1{font-size:28px}p{line-height:1.5}.notice{padding:14px;background:#293e51;border-left:4px solid #e5ab71}.controls{display:flex;align-items:center;gap:15px;flex-wrap:wrap;margin:18px 0}button,select{padding:9px;border:1px solid #829cb3;background:#304c64;color:white;border-radius:6px}input{width:310px}canvas{width:100%;height:560px;background:#182b3c;border-radius:10px}.values{display:flex;gap:24px;flex-wrap:wrap;margin:16px 0}a{color:#a2d6f9}small{color:#b9ccdd}</style><main><h1>Avion contre façade — premier contact A15</h1><p class="notice">Le prototype complet est lancé à <b>200 m/s</b> contre une façade déformable de trois étages. La fenêtre calculée atteint <b>10 ms, soit 0,01 seconde</b>. La masse, les matériaux et les assemblages existants sont conservés. Les résultats restent exploratoires : rupture, écrasement et délamination ne sont pas représentés, et les critères numériques échoués figurent dans le rapport.</p><div class="controls"><button id="play">Lecture ralentie</button><input id="time" type="range" min="0" value="0" step="1"><b id="label">Chargement des états natifs…</b><select id="view"><option value="full">Avion et façade</option><option value="close">Contact du nez</option></select><label><input id="structure" type="checkbox" style="width:auto"> Structure interne</label><label><input id="initial" type="checkbox" style="width:auto"> Position initiale</label></div><canvas id="canvas"></canvas><div id="values" class="values"></div><p><small>Vert : avion ; orange : façade ; gris : position initiale si activée. Déplacements natifs ×1, états échantillonnés tous les 0,5 ms environ, lecture artificiellement ralentie. Les formes affichées au-delà des limites matérielles servent au diagnostic ; elles ne décrivent pas une rupture historique. Aucun mouvement Blender ni trajet de pénétration n’est imposé.</small></p><p><a href="bilans_impact.svg">Comparer les deux calculs et leurs bilans</a> · <a href="../rapport_aircraft_a15.md">Rapport et limites</a></p></main><script>const D=PAYLOAD,PACK='PACKED';const cv=document.querySelector('#canvas'),ctx=cv.getContext('2d'),sl=document.querySelector('#time');let X,U,playing=false,last=0;sl.max=D.nt-1;async function init(){let b=Uint8Array.from(atob(PACK),c=>c.charCodeAt(0)),stream=new Blob([b]).stream().pipeThrough(new DecompressionStream('gzip')),a=await new Response(stream).arrayBuffer();if(a.byteLength!==D.nn*3*8+D.nt*D.nn*3*4)throw Error('Invalid native state sizes');X=new Float64Array(a,0,D.nn*3);U=new Float32Array(a,D.nn*3*8,D.nt*D.nn*3);draw();requestAnimationFrame(tick)}function draw(){if(!X)return;let b=cv.getBoundingClientRect(),k=+sl.value,close=document.querySelector('#view').value==='close';cv.width=b.width*devicePixelRatio;cv.height=b.height*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);ctx.clearRect(0,0,b.width,b.height);let sc=Math.min(b.width/(close?10:75),b.height/(close?7:38)),cx=close?0:10,cy=0,cz=close?0:0;function P(n,init){let j=n*3,o=k*D.nn*3+j,x=X[j]+(init?0:U[o])-cx,y=X[j+1]+(init?0:U[o+1])-cy,z=X[j+2]+(init?0:U[o+2])-cz;return[b.width/2+sc*(.819*x+.574*y),b.height/2-sc*(.94*z-.342*(-.574*x+.819*y))]}function faces(rows,col,alpha,init){ctx.strokeStyle=col;ctx.globalAlpha=alpha;ctx.lineWidth=close?.7:.5;for(let r of rows){if(close&&r.every(n=>X[n*3]>5||Math.abs(X[n*3+1])>6||Math.abs(X[n*3+2])>6))continue;let pts=r.map(n=>P(n,init));if(pts.every(p=>p[0]<0)||pts.every(p=>p[0]>b.width)||pts.every(p=>p[1]<0)||pts.every(p=>p[1]>b.height))continue;ctx.beginPath();pts.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));if(r.length>2)ctx.closePath();ctx.stroke()}}faces(D.wall,'#e4a16d',close?.55:.28,false);if(document.querySelector('#initial').checked)faces(D.triangles,'#a6b3bd',.12,true);faces(D.triangles,'#53d1b2',close?.65:.45,false);if(document.querySelector('#structure').checked)faces(D.beams,'#aacbe0',.25,false);ctx.globalAlpha=1;ctx.fillStyle='#dbeaf5';ctx.font='14px system-ui';ctx.fillText('États natifs — déplacements ×1',18,27);document.querySelector('#label').textContent=D.time_ms[k].toFixed(6)+' ms';document.querySelector('#values').innerHTML='<span>Impulsion X : '+(D.impulse_Ns[k]/1000).toFixed(3)+' kN·s</span><span>Énergie hors translation : '+(D.energy_J[k]/1e6).toFixed(3)+' MJ</span><span>Résidu : '+(D.residual_J[k]/1000).toFixed(3)+' kJ</span><span>Déplacement max. façade : '+D.facade_displacement_mm[k].toFixed(1)+' mm</span>'}sl.oninput=draw;window.onresize=draw;for(let id of ['view','structure','initial'])document.querySelector('#'+id).onchange=draw;document.querySelector('#play').onclick=()=>{playing=!playing;document.querySelector('#play').textContent=playing?'Pause':'Lecture ralentie'};function tick(t){if(playing&&t-last>300){sl.value=(+sl.value+1)%D.nt;last=t;draw()}requestAnimationFrame(tick)}init().catch(e=>document.querySelector('#label').textContent='Lecture indisponible : '+e.message);</script></html>'''
    html=html.replace('PAYLOAD',json.dumps(payload,separators=(',',':'))).replace('PACKED',base64.b64encode(compressed).decode());(dst/'impact_avion_facade.html').write_text(html,encoding='utf-8');(dst/'viewer_script_for_validation.js').write_text(html.split('<script>')[1].split('</script>')[0],encoding='utf-8')
    assert U.shape==(Dframes:=len(payload['time_ms']),len(X),3) and len(payload['facade_displacement_mm'])==Dframes and np.isfinite(U).all()
    provenance={'case':case,'native_displacement_scale':1,'no_geometry_time_interpolation':True,'sampled_native_frames':len(U),'native_time_unit':'ms','artificial_playback':True,'compressed_payload_bytes':len(compressed),'uncompressed_payload_sha256':hashlib.sha256(raw).hexdigest(),'gzip_roundtrip_exact':True,'data_schema_pass':True,'reportlab_version':reportlab.Version,'GUI_render_verified':False,'physical_impact_qualified':False};(dst/'provenance.json').write_text(json.dumps(provenance,indent=2),encoding='utf-8');print(provenance)

if __name__=='__main__':main()
